CREATE OR REPLACE FUNCTION public.nmis_list_audit_logs(p_limit integer DEFAULT 200, p_offset integer DEFAULT 0) RETURNS SETOF public.audit_logs LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'public', 'auth' AS $$ DECLARE nmis_role text := coalesce(auth.jwt() -> 'app_metadata' ->> 'nmis_role', ''); BEGIN IF nmis_role <> 'super-admin' THEN RAISE EXCEPTION 'permission denied for secure audit log contract' USING ERRCODE = '42501'; END IF; RETURN QUERY SELECT a.* FROM public.audit_logs AS a ORDER BY a.created_at DESC NULLS LAST, a.id DESC OFFSET greatest(coalesce(p_offset, 0), 0) LIMIT least(greatest(coalesce(p_limit, 200), 1), 500); END; $$; REVOKE ALL ON FUNCTION public.nmis_list_audit_logs(integer, integer) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.nmis_list_audit_logs(integer, integer) TO authenticated; CREATE OR REPLACE FUNCTION public.nmis_admin_snapshot_manifest() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'public', 'auth' AS $$ DECLARE nmis_role text := coalesce(auth.jwt() -> 'app_metadata' ->> 'nmis_role', ''); generated_at timestamptz := now(); BEGIN IF nmis_role <> 'super-admin' THEN RAISE EXCEPTION 'permission denied for admin snapshot contract' USING ERRCODE = '42501'; END IF; RETURN jsonb_build_object('format', 'nmis-snapshot-manifest-v1', 'generated_at', generated_at, 'database', jsonb_build_object('providers', (SELECT count(*) FROM public.providers), 'enrollees', (SELECT count(*) FROM public.enrollees), 'financial_records', (SELECT count(*) FROM public.financial_records), 'import_batches', (SELECT count(*) FROM public.import_batches), 'audit_logs', (SELECT count(*) FROM public.audit_logs), 'inspections', (SELECT count(*) FROM public.inspections), 'provider_documents', (SELECT count(*) FROM public.provider_documents)), 'note', 'This manifest contains protected-record counts and timestamp only. Full database backup is maintained by Supabase backup/PITR infrastructure.'); END; $$; REVOKE ALL ON FUNCTION public.nmis_admin_snapshot_manifest() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.nmis_admin_snapshot_manifest() TO authenticated;